window.__WB_TEXTBOOK__ = [{"id": "ross", "name": "Sheldon Ross《A First Course in Probability》(10th Ed.)", "author": "Sheldon M. Ross", "level": "组合直觉与随机模型", "chapters": [{"cid": "Ross-Ch.01-03", "title": "组合计数、概率公理与 Bayes 条件概率", "summary": "Ross 开篇以隔板法（Stars and Bars）与多项式系数奠定组合计数直觉，随后严格引入 Kolmogorov 概率三公理并推导出容斥原理（Inclusion-Exclusion）与匹配问题（Derangement）的概率极限 $1 - e^{-1}$。第 3 章核心在于条件概率的“样本空间缩减”与“全概率公式递归分解”：通过 $P(E) = \\sum P(E|F_i)P(F_i)$ 将复杂的序贯随机过程（如赌徒破产问题、条件期望递推）拆解为一步条件事件，并用 Bayes 公式定量刻画新证据对先验信念的实时修正，同时严格辨析事件两两独立与相互独立的差异。", "template_cpp": "【Bayes 公式与容斥原理核心骨架】\n1. 全概率与 Bayes 更新：\n$$P(H_i \\mid E) = \\frac{P(E \\mid H_i)P(H_i)}{\\sum_{j=1}^n P(E \\mid H_j)P(H_j)}$$\n2. 容斥原理：\n$$P\\left(\\bigcup_{i=1}^n E_i\\right) = \\sum_i P(E_i) - \\sum_{i<j} P(E_i E_j) + \\dots + (-1)^{n-1} P(E_1 \\cdots E_n)$$\n3. 赌徒破产一步递推：$P_i = p P_{i+1} + q P_{i-1}$。", "pitfalls": "混淆“两两独立”与“相互独立”（Bernstein 反例：均匀掷两枚硬币，$A$: 第1枚正，$B$: 第2枚正，$C$: 两枚相同，两两独立但 $P(ABC)=1/4 \\neq 1/8$）；使用 Bayes 公式时忽略基础先验率（Base Rate Fallacy，如低发病率疾病高假阳性率误诊）；在隔板法中混淆非负整数解与正整数解的加 $1$ 偏移。", "workbench_tags": ["组合计数", "容斥原理", "Bayes公式", "条件独立"], "problems": [{"oj": "教材精选题", "pid": "Ross-1.1", "title": "经典错排（信封匹配）问题的容斥求解", "diff": "基础", "hint": "破题思路：$n$ 封信随机装入 $n$ 个信封，求至少有一封信装对的概率。完整解答：设 $E_i$ 为第 $i$ 封信装对的事件。固定任意 $k$ 封信装对，其余 $n-k$ 封任意排列，故 $P(E_{i_1}\\cdots E_{i_k}) = \\frac{(n-k)!}{n!}$。由对称性，取 $k$ 个交集的项共有 $\\binom{n}{k}$ 个。代入容斥原理：$P(\\bigcup_{i=1}^n E_i) = \\sum_{k=1}^n (-1)^{k-1} \\binom{n}{k} \\frac{(n-k)!}{n!} = \\sum_{k=1}^n \\frac{(-1)^{k-1}}{k!} \\to 1 - e^{-1} \\approx 0.6321$。"}, {"oj": "教材精选题", "pid": "Ross-1.2", "title": "Monty Hall 三门问题的条件概率严格推导", "diff": "基础", "hint": "破题思路：参赛者选 $1$ 号门，主持人知情且必打开 $2,3$ 号中无车的一扇（如 $3$ 号门），问换门中奖概率。完整解答：设 $C_i$ 为车在 $i$ 号门（先验 $1/3$），$O_3$ 为主持人打开 $3$ 号门。则 $P(O_3|C_1) = 1/2$（两门均无车随机开），$P(O_3|C_2) = 1$（不能开有车的 $2$ 号门），$P(O_3|C_3) = 0$。由 Bayes 公式，换门（车在 $2$ 号门）后验概率为 $P(C_2|O_3) = \\frac{1\\cdot 1/3}{\\frac{1}{2}\\cdot\\frac{1}{3} + 1\\cdot\\frac{1}{3} + 0} = \\frac{2}{3}$。"}, {"oj": "教材精选题", "pid": "Ross-1.3", "title": "赌徒破产问题 (Gambler's Ruin) 的差分方程解", "diff": "压轴", "hint": "破题思路：甲初始资本 $i$，每局胜率 $p$ 赢 $1$ 元、败率 $q=1-p$ 输 $1$ 元，求在破产前先达到目标 $N$ 元的概率 $P_i$。完整解答：边界 $P_0=0, P_N=1$。由全概率公式 $P_i = p P_{i+1} + q P_{i-1}$，改写为 $p(P_{i+1}-P_i) = q(P_i - P_{i-1})$。当 $p \\neq q$ 时，差分呈等比数列 $P_{i+1}-P_i = (q/p)^i P_1$，累加得 $P_i = P_1 \\frac{1-(q/p)^i}{1-(q/p)}$。代入 $P_N=1$ 解得 $P_i = \\frac{1-(q/p)^i}{1-(q/p)^N}$；当 $p=q=1/2$ 时 $P_i = i/N$。"}, {"oj": "教材精选题", "pid": "Ross-1.4", "title": "非负整数解计数与多维隔板法应用", "diff": "中档", "hint": "破题思路：求不定方程 $x_1 + x_2 + x_3 + x_4 = 12$ 满足 $x_1 \\ge 2, x_2 \\ge 0, x_3 \\ge 1, x_4 \\ge 3$ 的整数解个数。完整解答：作变量平移消除下界差异：令 $y_1 = x_1-2, y_2 = x_2, y_3 = x_3-1, y_4 = x_4-3$，则等价于求 $y_1 + y_2 + y_3 + y_4 = 6$ 的非负整数解个数。将 $6$ 个球与 $4-1=3$ 个隔板排列，方案数为 $\\binom{6+4-1}{4-1} = \\binom{9}{3} = 84$。"}]}, {"cid": "Ross-Ch.04-05", "title": "离散与连续随机变量、Poisson 过程与无记忆性", "summary": "第 4、5 章系统建立一维随机变量的概率分布律（PMF）与概率密度函数（PDF）体系。离散部分以 Bernoulli、二项、几何、超几何与 Poisson 分布为主线，重点推导二项分布 $B(n,p)$ 在 $np=\\lambda$ 保持常数时的 Poisson 极限定理。连续部分深入探讨均匀、正态与指数分布，揭示**指数分布是唯一具有无记忆性的连续分布**，并阐明其与 Poisson 过程到达时间间隔的深刻对偶性（第 $k$ 次到达时间服从 Gamma 分布）。此外，引入单调函数与一般变换的 Jacobian 密度变换公式，完成从随机变量到概率分布的精确映射。", "template_cpp": "【Poisson 极限与随机变量变换公式】\n1. Poisson 逼近二项分布（$n\\to\\infty, p\\to 0, np=\\lambda$）：\n$$\\binom{n}{k} p^k (1-p)^{n-k} \\approx \\frac{\\lambda^k e^{-\\lambda}}{k!}$$\n2. 连续变量单调变换 $Y = g(X)$ 的密度公式：\n$$f_Y(y) = f_X(g^{-1}(y)) \\left|\\frac{d}{dy} g^{-1}(y)\\right|$$\n3. 指数分布无记忆性：$P(X > s+t \\mid X > s) = P(X > t) = e^{-\\lambda t}$。", "pitfalls": "误以为概率密度函数值 $f(x)$ 必须 $\\le 1$（密度可以远大于 $1$，只要总积分为 $1$）；做随机变量函数变换 $Y = X^2$ 时因 $g$ 非单调而漏掉负半轴分支（正确应为 $f_Y(y) = \\frac{1}{2\\sqrt{y}}[f_X(\\sqrt{y}) + f_X(-\\sqrt{y})]$）；混淆正态分布 $\\mathcal{N}(\\mu, \\sigma^2)$ 记号中的第二参数是方差 $\\sigma^2$ 还是标准差 $\\sigma$。", "workbench_tags": ["Poisson分布", "指数分布", "无记忆性", "密度变换"], "problems": [{"oj": "教材精选题", "pid": "Ross-2.1", "title": "几何分布与指数分布无记忆性的统一证明", "diff": "基础", "hint": "破题思路：证明若非负连续随机变量 $X$ 满足 $P(X > s+t) = P(X > s)P(X > t)$，则 $X$ 必服从指数分布。完整解答：令生存函数 $\\bar{F}(t) = P(X > t)$，满足 Cauchy 乘性函数方程 $\\bar{F}(s+t) = \\bar{F}(s)\\bar{F}(t)$。由单调非增性，先推 $\\bar{F}(n) = \\bar{F}(1)^n$，再推有理数 $\\bar{F}(p/q) = \\bar{F}(1)^{p/q}$，由右连续性扩展至全部 $t \\ge 0$：$\\bar{F}(t) = e^{-\\lambda t}$（其中 $\\lambda = -\\ln \\bar{F}(1) > 0$）。"}, {"oj": "教材精选题", "pid": "Ross-2.2", "title": "对数正态分布与卡方分布密度函数推导", "diff": "中档", "hint": "破题思路：设 $Z \\sim \\mathcal{N}(0,1)$，求 $Y = Z^2$（即 $\\chi^2(1)$）的概率密度函数。完整解答：对 $y > 0$，$F_Y(y) = P(Z^2 \\le y) = P(-\\sqrt{y} \\le Z \\le \\sqrt{y}) = 2\\Phi(\\sqrt{y}) - 1$。两边对 $y$ 求导：$f_Y(y) = 2\\phi(\\sqrt{y}) \\cdot \\frac{1}{2\\sqrt{y}} = \\frac{1}{\\sqrt{2\\pi y}} e^{-y/2}$（$y>0$），恰为 $\\Gamma(1/2, 1/2)$ 分布。"}, {"oj": "教材精选题", "pid": "Ross-2.3", "title": "逆变换采样 (Inverse Transform Sampling) 原理", "diff": "中档", "hint": "破题思路：设 $U \\sim \\text{Uniform}(0,1)$，$F$ 为严格递增连续分布函数，证 $X = F^{-1}(U)$ 服从分布 $F$。完整解答：对任意 $x \\in \\mathbb{R}$，$P(X \\le x) = P(F^{-1}(U) \\le x) = P(U \\le F(x))$（利用 $F$ 严格递增）。因 $F(x) \\in (0,1)$ 且 $U$ 均匀分布，$P(U \\le F(x)) = F(x)$。例如 $X = -\\frac{1}{\\lambda}\\ln(1-U)$ 即生成指数分布随机数。"}, {"oj": "教材精选题", "pid": "Ross-2.4", "title": "泊松过程合并与稀疏化（Thinning）定理", "diff": "压轴", "hint": "破题思路：某系统按速率 $\\lambda$ 的 Poisson 过程接收请求，每个请求以独立概率 $p$ 被标记为 A 类，$(1-p)$ 为 B 类。证明时间 $t$ 内 A 类与 B 类请求数 $N_A(t), N_B(t)$ 独立且分别服从 $\\text{Poisson}(\\lambda p t)$ 与 $\\text{Poisson}(\\lambda(1-p)t)$。完整解答：用全概率公式计算联合分布 $P(N_A=k, N_B=m) = P(N_A=k, N_B=m \\mid N=k+m) P(N=k+m) = \\binom{k+m}{k} p^k (1-p)^m \\cdot \\frac{(\\lambda t)^{k+m} e^{-\\lambda t}}{(k+m)!} = \\frac{(\\lambda pt)^k e^{-\\lambda pt}}{k!} \\cdot \\frac{(\\lambda(1-p)t)^m e^{-\\lambda(1-p)t}}{m!}$。联合分布等于边缘乘积，独立性得证！"}]}, {"cid": "Ross-Ch.06", "title": "联合分布、次序统计量与二维 Jacobian 变换", "summary": "第 6 章从单变量迈向多维联合随机向量 $(X, Y)$，阐明边缘分布、独立性的乘积判别法以及和变量卷积公式 $f_{X+Y}(a) = \\int f_X(a-y)f_Y(y)dy$（由此证明独立正态与独立 Poisson 变量之和仍保持分布族封闭性）。本章两大高光亮点为**次序统计量（Order Statistics）**与**二维变换 Jacobian 行列式**：利用多项分布直观推导第 $k$ 小值 $X_{(k)}$ 与极差 $R = X_{(n)} - X_{(1)}$ 的密度函数，并用微元面积伸缩因子 $|\\det J|$ 完美解释 Box-Muller 变换及 Beta-Gamma 独立性奇迹。", "template_cpp": "【次序统计量与二维 Jacobian 变换公式】\n1. $n$ 个 i.i.d. 样本（密度 $f$, 分布 $F$）的第 $k$ 顺序统计量密度：\n$$f_{X_{(k)}}(x) = \\frac{n!}{(k-1)!(n-k)!} [F(x)]^{k-1} [1-F(x)]^{n-k} f(x)$$\n2. 二维可逆变换 $(u,v) = g(x,y)$，反解 $(x,y) = h(u,v)$：\n$$f_{U,V}(u,v) = f_{X,Y}(x,y) \\cdot \\left|\\det \\frac{\\partial(x,y)}{\\partial(u,v)}\\right|$$", "pitfalls": "应用二维 Jacobian 变换时把正向偏导矩阵行列式 $\\left|\\frac{\\partial(u,v)}{\\partial(x,y)}\\right|$ 当成反向 $\\left|\\frac{\\partial(x,y)}{\\partial(u,v)}\\right|$（两者互为倒数）；做卷积积分或变换求边缘密度时未画图确定 $(u,v)$ 的真实定义域边界，导致积分限出错。", "workbench_tags": ["联合分布", "卷积公式", "次序统计量", "Jacobian变换"], "problems": [{"oj": "教材精选题", "pid": "Ross-3.1", "title": "Box-Muller 变换生成独立标准正态随机数", "diff": "中档", "hint": "破题思路：设 $X, Y$ i.i.d. $\\sim \\mathcal{N}(0,1)$，作极坐标变换 $R^2 = X^2+Y^2, \\Theta = \\arctan(Y/X)$，求 $R^2$ 与 $\\Theta$ 分布。完整解答：变换 $x = r\\cos\\theta, y = r\\sin\\theta$ 的 Jacobian 行列式为 $r$。令 $d = r^2$，则 $dx\\,dy = r\\,dr\\,d\\theta = \\frac{1}{2} dd\\,d\\theta$。联合密度 $f_{X,Y}(x,y) = \\frac{1}{2\\pi} e^{-(x^2+y^2)/2}$ 变换后得 $f_{D, \\Theta}(d, \\theta) = \\frac{1}{2\\pi} \\cdot \\frac{1}{2} e^{-d/2}$（$d>0, \\theta\\in(0,2\\pi)$）。故 $D \\sim \\text{Exp}(1/2)$ 且 $\\Theta \\sim \\text{Uniform}(0,2\\pi)$ 相互独立！"}, {"oj": "教材精选题", "pid": "Ross-3.2", "title": "独立 Gamma 变量的和与商的独立性（Lukacs 定理）", "diff": "压轴", "hint": "破题思路：设 $X \\sim \\Gamma(\\alpha, \\lambda), Y \\sim \\Gamma(\\beta, \\lambda)$ 独立，证 $U = X+Y$ 与 $V = \\frac{X}{X+Y}$ 独立且分别服从 $\\Gamma(\\alpha+\\beta, \\lambda)$ 与 $\\text{Beta}(\\alpha, \\beta)$。完整解答：反解 $x = uv, y = u(1-v)$，Jacobian 行列式 $\\left|\\det\\begin{pmatrix} v & u \\\\ 1-v & -u \\end{pmatrix}\\right| = u$。代入联合密度得 $f_{U,V}(u,v) = \\frac{\\lambda^{\\alpha+\\beta}}{\\Gamma(\\alpha)\\Gamma(\\beta)} u^{\\alpha+\\beta-1} e^{-\\lambda u} v^{\\alpha-1}(1-v)^{\\beta-1}$。变量 $u, v$ 完全分离，独立性与各自边缘分布立得！"}, {"oj": "教材精选题", "pid": "Ross-3.3", "title": "均匀分布次序统计量极差 $R = X_{(n)} - X_{(1)}$ 的分布", "diff": "中档", "hint": "破题思路：设 $X_1,\\dots,X_n$ i.i.d. $\\sim \\text{Uniform}(0,1)$，求 $R = X_{(n)} - X_{(1)}$ 的密度。完整解答：$(X_{(1)}, X_{(n)})$ 联合密度为 $n(n-1)(y-x)^{n-2}$（$0<x<y<1$）。作变换 $r = y-x, s = x$（$J=1$），积分 $s$ 从 $0$ 到 $1-r$：$f_R(r) = \\int_0^{1-r} n(n-1) r^{n-2} ds = n(n-1) r^{n-2} (1-r)$（$0<r<1$），即 $\\text{Beta}(n-1, 2)$ 分布。"}, {"oj": "教材精选题", "pid": "Ross-3.4", "title": "Buffon 投针问题与几何概率积分", "diff": "基础", "hint": "破题思路：平行线间距为 $D$，针长 $L \\le D$，随机投针求与线相交的概率。完整解答：设针中心距最近直线距离 $X \\sim \\text{Uniform}(0, D/2)$，针与平行线夹角 $\\Theta \\sim \\text{Uniform}(0, \\pi/2)$ 且两者独立。相交充要条件为 $X \\le \\frac{L}{2}\\sin\\Theta$。在矩形 $[0, D/2]\\times[0, \\pi/2]$ 上积分得概率 $P = \\frac{1}{(D/2)(\\pi/2)} \\int_0^{\\pi/2} \\frac{L}{2}\\sin\\theta\\,d\\theta = \\frac{2L}{\\pi D}$。"}]}, {"cid": "Ross-Ch.07", "title": "数学期望、条件期望与全方差公式", "summary": "第 7 章是 Ross 全书最具魅力的篇章，将期望的线性性 $E[\\sum X_i] = \\sum E[X_i]$（**无需独立性！**）发挥到极致，配合“示性函数（Indicator Variable）”技巧秒杀收集优惠券问题（Coupon Collector）与随机图期望计数。更进一步，深入剖析条件期望 $E[X|Y]$ 作为随机变量的性质，推导出**全期望公式（Law of Total Expectation）** $E[X] = E[E[X|Y]]$ 与**全方差公式（Eve's Law）** $\\text{Var}(X) = E[\\text{Var}(X|Y)] + \\text{Var}(E[X|Y])$，为随机过程、马尔可夫决策及贝叶斯预测提供强力工具。", "template_cpp": "【示性函数技巧与全期望/全方差公式】\n1. 示性函数拆解：$X = \\sum_{i=1}^n I_i$，即使 $I_i$ 相关，依然恒有 $E[X] = \\sum_{i=1}^n P(A_i)$。\n2. 全期望（Tower Property）：$E[X] = E[E[X \\mid Y]]$。\n3. 全方差（Variance Decomposition）：\n$$\\text{Var}(X) = E[\\text{Var}(X \\mid Y)] + \\text{Var}(E[X \\mid Y])$$\n4. 最佳均方预测：最小化 $E[(X - g(Y))^2]$ 的函数唯一为 $g(Y) = E[X \\mid Y]$。", "pitfalls": "误以为 $E[XY] = E[X]E[Y]$ 无需独立性（仅线性加法无需独立，乘法需要不相关）；在计算 $\\text{Var}(\\sum X_i)$ 时忽略交叉协方差项 $2\\sum_{i<j} \\text{Cov}(X_i, X_j)$；错把条件期望 $E[X|Y]$ 当成常数而非依赖随机变量 $Y$ 的随机变量。", "workbench_tags": ["数学期望", "示性函数", "条件期望", "全方差公式"], "problems": [{"oj": "教材精选题", "pid": "Ross-4.1", "title": "示性函数秒杀“帽子错排”的期望与方差", "diff": "基础", "hint": "破题思路：$n$ 个人随机拿帽子，求拿对自己帽子的人数 $X$ 的期望与方差。完整解答：令 $I_i = 1$ 若第 $i$ 人拿对，否则 $0$。则 $E[I_i] = 1/n$，由期望线性性 $E[X] = \\sum_{i=1}^n E[I_i] = 1$（与 $n$ 无关！）。求方差需算 $E[X^2] = \\sum_i E[I_i^2] + \\sum_{i\\neq j} E[I_i I_j] = n\\cdot\\frac{1}{n} + n(n-1)\\cdot \\frac{1}{n(n-1)} = 2$。故 $\\text{Var}(X) = E[X^2] - (E[X])^2 = 2 - 1 = 1$！"}, {"oj": "教材精选题", "pid": "Ross-4.2", "title": "优惠券收集问题 (Coupon Collector) 的期望等待次数", "diff": "中档", "hint": "破题思路：共有 $N$ 种不同卡片，每次等概率抽一张，求集齐所有 $N$ 种卡片所需的期望抽取次数。完整解答：将过程分解为 $N$ 个独立阶段：$T = T_0 + T_1 + \\dots + T_{N-1}$，其中 $T_k$ 为已有 $k$ 种后抽到第 $k+1$ 种新卡片的等待次数。处于状态 $k$ 时抽到新卡概率为 $p_k = \\frac{N-k}{N}$，故 $T_k \\sim \\text{Geom}(p_k)$，期望 $E[T_k] = \\frac{N}{N-k}$。总期望 $E[T] = N \\sum_{k=0}^{N-1} \\frac{1}{N-k} = N H_N \\approx N \\ln N$。"}, {"oj": "教材精选题", "pid": "Ross-4.3", "title": "随机个数求和（Wald 等式与复合分布方差）", "diff": "中档", "hint": "破题思路：设 $N$ 为非负整数随机变量，$X_1, X_2, \\dots$ i.i.d. 且与 $N$ 独立，求 $S = \\sum_{i=1}^N X_i$ 的期望与方差。完整解答：(1) 全期望：$E[S] = E[E[S|N]] = E[N \\mu] = \\mu E[N]$；(2) 全方差：$\\text{Var}(S|N) = N \\sigma^2$，$E[S|N] = N \\mu$，代入 Eve's Law 得 $\\text{Var}(S) = E[N\\sigma^2] + \\text{Var}(N\\mu) = \\sigma^2 E[N] + \\mu^2 \\text{Var}(N)$。"}, {"oj": "教材精选题", "pid": "Ross-4.4", "title": "连续掷硬币直至出现连续两个正面 (HH) 的期望次数", "diff": "压轴", "hint": "破题思路：利用首步分析（First-Step Analysis）与条件期望。完整解答：设从初始状态出发期望次数为 $E$。第 1 次掷：以 $1/2$ 概率出反面 $T$（浪费 1 步回到初始状态，总期望 $1+E$）；以 $1/2$ 概率出正面 $H$，此时若第 2 次出 $H$（概率 $1/2$）则结束（共 2 步），若第 2 次出 $T$（概率 $1/2$）则浪费 2 步回到初始状态（共 $2+E$ 步）。列方程：$E = \\frac{1}{2}(1+E) + \\frac{1}{4}(2) + \\frac{1}{4}(2+E)$，解得 $E = 6$。"}]}, {"cid": "Ross-Ch.08-09", "title": "大数定律、中心极限定理与 Markov 链初探", "summary": "第 8–9 章为 Ross 全书的极限理论与随机过程收官。从 Markov 不等式与 Chebyshev 不等式出发，严格证明弱大数定律（WLLN）与强大数定律（SLLN），揭示频率稳定性的数学本质。进而引入矩母函数（MGF）证明独立同分布求和的标准化极限服从标准正态分布——Lindeberg-Lévy 中心极限定理（CLT），解释自然界与误差分析中正态分布无处不在的原因。第 9 章拓展至离散时间 Markov 链、信息熵 $H(X) = -\\sum p_i \\log p_i$ 与平稳分布，为后续随机过程课程铺设完美接口。", "template_cpp": "【三大核心不等式与中心极限定理 (CLT)】\n1. Markov 不等式（$X\\ge 0, a>0$）：$P(X \\ge a) \\le \\frac{E[X]}{a}$。\n2. Chebyshev 不等式：$P(|X - \\mu| \\ge k\\sigma) \\le \\frac{1}{k^2}$。\n3. Chernoff 界：$P(X \\ge a) \\le \\min_{t>0} e^{-ta} M_X(t)$。\n4. 中心极限定理：$S_n = \\sum_{i=1}^n X_i$（i.i.d. 均值 $\\mu$ 方差 $\\sigma^2$），则 $\\frac{S_n - n\\mu}{\\sigma\\sqrt{n}} \\xrightarrow{d} \\mathcal{N}(0,1)$。", "pitfalls": "应用 Markov 不等式时忘记随机变量必须**非负**；用正态分布近似二项分布时在 $n$ 较小处漏掉连续性修正（Continuity Correction $\\pm 0.5$）；混淆依概率收敛（弱大数定律）与几乎必然收敛（强大数定律）的区别。", "workbench_tags": ["大数定律", "中心极限定理", "Chebyshev不等式", "矩母函数"], "problems": [{"oj": "教材精选题", "pid": "Ross-5.1", "title": "Chebyshev 不等式估计样本量（民意调查误差控制）", "diff": "基础", "hint": "破题思路：某选民支持率未知为 $p$，抽取 $n$ 人调查得样本比例 $\\hat{p}_n$，用 Chebyshev 不等式确定保证 $P(|\\hat{p}_n - p| < 0.02) \\ge 0.95$ 的最小 $n$。完整解答：$E[\\hat{p}_n] = p$，$\\text{Var}(\\hat{p}_n) = \\frac{p(1-p)}{n} \\le \\frac{1}{4n}$。由 Chebyshev 不等式 $P(|\\hat{p}_n - p| \\ge 0.02) \\le \\frac{1/(4n)}{0.02^2} \\le 0.05$，解得 $n \\ge \\frac{1}{4 \\times 0.0004 \\times 0.05} = 12500$。"}, {"oj": "教材精选题", "pid": "Ross-5.2", "title": "中心极限定理近似计算泊松/二项和概率", "diff": "中档", "hint": "破题思路：某设备每天独立消耗芯片数均值 $2$、方差 $1$，求 $100$ 天总消耗量超过 $215$ 片的近似概率。完整解答：设 $S_{100} = \\sum_{i=1}^{100} X_i$，则 $\\mu_S = 200$，$\\sigma_S = \\sqrt{100\\times 1} = 10$。应用连续性修正，$P(S_{100} > 215) = P(S_{100} \\ge 216) \\approx P\\left(Z \\ge \\frac{215.5 - 200}{10}\\right) = 1 - \\Phi(1.55) \\approx 0.0606$。"}, {"oj": "教材精选题", "pid": "Ross-5.3", "title": "Chernoff 界推导二项分布尾部指数衰减上界", "diff": "压轴", "hint": "破题思路：设 $X \\sim B(n, p)$，已知 $M_X(t) = (1 - p + p e^t)^n$，推导 $P(X \\ge a)$（$a > np$）的 Chernoff 指数界。完整解答：对任意 $t>0$，$P(X \\ge a) \\le e^{-ta} (1 - p + pe^t)^n$。记 $g(t) = -ta + n\\ln(1-p+pe^t)$，求导令 $g'(t)=0$ 得 $e^t = \\frac{a(1-p)}{(n-a)p}$（当 $a<n$ 时）。回代即得 KL 散度形式的上界 $P(X \\ge a) \\le \\exp\\left(-n D_{KL}\\left(\\frac{a}{n} \\parallel p\\right)\\right)$，衰减速度远快于 Chebyshev 多项式界。"}, {"oj": "教材精选题", "pid": "Ross-5.4", "title": "利用大数定律证明 Weierstrass 多项式逼近定理（Bernstein 构造）", "diff": "压轴", "hint": "破题思路：对 $[0,1]$ 上连续函数 $f(x)$，构造 Bernstein 多项式 $B_n(x) = \\sum_{k=0}^n f(k/n)\\binom{n}{k}x^k(1-x)^{n-k}$，证明 $B_n(x) \\rightrightarrows f(x)$。完整解答：注意到 $B_n(x) = E[f(S_n/n)]$，其中 $S_n \\sim B(n, x)$。由 $f$ 一致连续，对 $\\varepsilon>0$ 取 $\\delta>0$。拆开期望 $|B_n(x) - f(x)| \\le E[|f(S_n/n)-f(x)|]$，按 $|S_n/n - x| < \\delta$ 与 $\\ge \\delta$ 拆分：前者 $< \\varepsilon/2$；后者用有界性 $2M$ 与 Chebyshev 不等式 $P(|S_n/n - x| \\ge \\delta) \\le \\frac{x(1-x)}{n\\delta^2} \\le \\frac{1}{4n\\delta^2}$，取 $n$ 足够大即可使整体 $< \\varepsilon$。"}]}]}, {"id": "sheng", "name": "盛骤《概率论与数理统计》（第5版）", "author": "盛骤、谢式千、潘承毅", "level": "经典数理统计与工程推断", "chapters": [{"cid": "Sheng-Ch.01-03", "title": "多维随机变量分布、协方差与二维正态", "summary": "盛骤教材第 1–3 章以严谨的分布函数 $F(x,y) = P\\{X\\le x, Y\\le y\\}$ 为核心，系统打通离散联合分布律与连续联合密度之间的边缘、条件分布计算。特别深入剖析二维正态分布 $\\mathcal{N}(\\mu_1, \\mu_2; \\sigma_1^2, \\sigma_2^2; \\rho)$：不仅导出其边缘分布仍为一维正态，条件分布 $Y|X=x$ 亦为线性回归正态分布，更确立了“二维正态分布中不相关（$\\rho=0$）等价于相互独立”这一考研与工程高频结论，以及正态变量线性组合的正态封闭性。", "template_cpp": "【二维正态分布条件分布与独立性判据】\n若 $(X,Y) \\sim \\mathcal{N}(\\mu_1, \\mu_2; \\sigma_1^2, \\sigma_2^2; \\rho)$，则：\n1. 边缘分布：$X \\sim \\mathcal{N}(\\mu_1, \\sigma_1^2)$，$Y \\sim \\mathcal{N}(\\mu_2, \\sigma_2^2)$。\n2. 条件分布：$Y \\mid (X=x) \\sim \\mathcal{N}\\left(\\mu_2 + \\rho\\frac{\\sigma_2}{\\sigma_1}(x-\\mu_1),\\; \\sigma_2^2(1-\\rho^2)\\right)$。\n3. 独立性：$X$ 与 $Y$ 相互独立 $\\iff \\rho = 0$（一般分布不成立，仅联合正态成立）。", "pitfalls": "将“不相关 $\\implies$ 独立”推广到非正态分布（经典反例：$X \\sim \\mathcal{N}(0,1), Y = X^2$，则 $\\text{Cov}(X,Y)=E[X^3]=0$ 不相关但明显函数相关）；甚至即使 $X, Y$ 边缘均为正态且不相关，若不服从**联合**二维正态，仍可能不独立；求 $Z = X+Y$ 分段密度时忽略积分上下限交集导致结果超出值域。", "workbench_tags": ["二维正态", "条件分布", "不相关与独立", "分布函数"], "problems": [{"oj": "教材精选题", "pid": "Sheng-1.1", "title": "均匀分布区域上的条件密度与独立性检验", "diff": "基础", "hint": "破题思路：设 $(X,Y)$ 在三角形区域 $D = \\{(x,y): 0<x<1, 0<y<x\\}$ 上服从均匀分布，求边缘密度与 $f_{Y|X}(y|x)$。完整解答：$D$ 的面积为 $1/2$，故 $f(x,y) = 2$（在 $D$ 上）。边缘密度 $f_X(x) = \\int_0^x 2\\,dy = 2x$（$0<x<1$）；$f_Y(y) = \\int_y^1 2\\,dx = 2(1-y)$（$0<y<1$）。因 $f(x,y) \\neq f_X(x)f_Y(y)$ 不独立。条件密度 $f_{Y|X}(y|x) = \\frac{2}{2x} = \\frac{1}{x}$（$0<y<x$），即 $\\text{Uniform}(0,x)$。"}, {"oj": "教材精选题", "pid": "Sheng-1.2", "title": "二维正态线性组合的独立性构造", "diff": "中档", "hint": "破题思路：设 $X, Y$ i.i.d. $\\sim \\mathcal{N}(0, \\sigma^2)$，判断 $U = X+Y$ 与 $V = X-Y$ 是否独立。完整解答：$(X,Y)$ 独立正态故 $(U,V)$ 服从联合二维正态分布！计算协方差：$\\text{Cov}(U,V) = \\text{Cov}(X+Y, X-Y) = \\text{Var}(X) - \\text{Var}(Y) = \\sigma^2 - \\sigma^2 = 0$。由于联合正态分布不相关即独立，故 $U$ 与 $V$ 相互独立（此性质是正态样本均值与方差独立的基石）。"}, {"oj": "教材精选题", "pid": "Sheng-1.3", "title": "最值随机变量 $\\max(X,Y)$ 与 $\\min(X,Y)$ 的分布推导", "diff": "基础", "hint": "破题思路：设 $X, Y$ 独立，分布函数分别为 $F_X, F_Y$，求 $M = \\max(X,Y)$ 与 $N = \\min(X,Y)$ 的分布函数。完整解答：$F_M(z) = P(\\max(X,Y) \\le z) = P(X\\le z, Y\\le z) = F_X(z) F_Y(z)$；$F_N(z) = 1 - P(\\min(X,Y) > z) = 1 - P(X>z, Y>z) = 1 - [1-F_X(z)][1-F_Y(z)]$。若 $X, Y$ i.i.d. $\\sim \\text{Exp}(\\lambda)$，则 $\\min(X,Y) \\sim \\text{Exp}(2\\lambda)$。"}, {"oj": "教材精选题", "pid": "Sheng-1.4", "title": "边缘正态但不独立的联合分布经典反例构造", "diff": "压轴", "hint": "破题思路：构造不独立的两个标准正态随机变量。完整解答：设 $X \\sim \\mathcal{N}(0,1)$，另取独立随机符号 $S$（以概率 $1/2$ 取 $\\pm 1$），令 $Y = S X$。显然 $Y$ 对称且 $|Y|=|X|$，故 $Y \\sim \\mathcal{N}(0,1)$。计算 $\\text{Cov}(X,Y) = E[SX^2] = E[S]E[X^2] = 0$，即不相关。但 $|Y| = |X|$ 说明两者高度相依（$P(|Y|\\le 1 \\mid |X|>2) = 0 \\neq P(|Y|\\le 1)$），$(X,Y)$ 并不服从联合二维正态分布。"}]}, {"cid": "Sheng-Ch.04-06", "title": "样本分布、三大抽样分布与 Cochran 定理", "summary": "第 6 章是从概率论跨入数理统计的分水岭。在定义简单随机样本 $X_1,\\dots,X_n$、经验分布函数与样本均值 $\\bar{X}$、样本方差 $S^2 = \\frac{1}{n-1}\\sum (X_i-\\bar{X})^2$ 的基础上，系统构造数理统计三大核心抽样分布：$\\chi^2(n)$ 分布、$t(n)$ 分布与 $F(n_1, n_2)$ 分布。核心理论高峰在于正态总体下的 **Fisher/Cochran 定理**：当 $X_i \\sim \\mathcal{N}(\\mu, \\sigma^2)$ 时，$\bar{X} \\sim \\mathcal{N}(\\mu, \\sigma^2/n)$ 与 $(n-1)S^2/\\sigma^2 \\sim \\chi^2(n-1)$ **相互独立**，从而立即推出枢轴量 $\\frac{\\bar{X}-\\mu}{S/\\sqrt{n}} \\sim t(n-1)$，为小样本精确推断奠定基础。", "template_cpp": "【正态总体四大抽样分布结论速查】\n设 $X_1,\\dots,X_n$ i.i.d. $\\sim \\mathcal{N}(\\mu, \\sigma^2)$：\n1. $\\bar{X} \\sim \\mathcal{N}(\\mu, \\sigma^2/n)$，即 $\\frac{\\bar{X}-\\mu}{\\sigma/\\sqrt{n}} \\sim \\mathcal{N}(0,1)$。\n2. $\\frac{(n-1)S^2}{\\sigma^2} = \\frac{1}{\\sigma^2}\\sum_{i=1}^n (X_i - \\bar{X})^2 \\sim \\chi^2(n-1)$（自由度减 $1$）。\n3. $\\bar{X}$ 与 $S^2$ 相互独立！\n4. 枢轴量：$\\frac{\\bar{X}-\\mu}{S/\\sqrt{n}} \\sim t(n-1)$；双样本方差比：$\\frac{S_1^2/\\sigma_1^2}{S_2^2/\\sigma_2^2} \\sim F(n_1-1, n_2-1)$。", "pitfalls": "混淆 $\\frac{1}{n}\\sum(X_i-\\mu)^2$（已知 $\\mu$，服从 $\\chi^2(n)/n$）与 $\\frac{1}{n-1}\\sum(X_i-\\bar{X})^2$（未知 $\\mu$ 用 $\\bar{X}$ 替代，自由度降为 $n-1$）；忘记 $t$ 分布与 $F$ 分布构造中要求分子分母必须**相互独立**；误以为 $t(1)$（即 Cauchy 分布）存在数学期望。", "workbench_tags": ["抽样分布", "卡方分布", "t分布", "样本方差独立性"], "problems": [{"oj": "教材精选题", "pid": "Sheng-2.1", "title": "样本方差 $S^2$ 除以 $n-1$ 的无偏性证明", "diff": "基础", "hint": "破题思路：计算 $E\\left[\\sum_{i=1}^n (X_i - \\bar{X})^2\\right]$（不依赖正态假设）。完整解答：利用恒等式 $\\sum_{i=1}^n (X_i - \\bar{X})^2 = \\sum_{i=1}^n (X_i - \\mu)^2 - n(\\bar{X} - \\mu)^2$。两边取期望：$E[\\sum (X_i-\\mu)^2] = n\\sigma^2$，且 $E[n(\\bar{X}-\\mu)^2] = n \\text{Var}(\\bar{X}) = n \\cdot \\frac{\\sigma^2}{n} = \\sigma^2$。相减得 $(n-1)\\sigma^2$，故 $E[S^2] = \\sigma^2$。"}, {"oj": "教材精选题", "pid": "Sheng-2.2", "title": "Helmert 正交变换证明正态样本 $\\bar{X}$ 与 $S^2$ 独立性", "diff": "压轴", "hint": "破题思路：构造第一行为 $\\frac{1}{\\sqrt{n}}(1,1,\\dots,1)$ 的 $n\\times n$ 正交矩阵 $A$，令 $\\mathbf{Y} = A\\mathbf{X}$。完整解答：因 $\\mathbf{X} \\sim \\mathcal{N}(\\mu\\mathbf{1}, \\sigma^2 I)$ 且 $A$ 正交，故 $Y_1,\\dots,Y_n$ 仍相互独立正态，方差均为 $\\sigma^2$。其中 $Y_1 = \\sqrt{n}\\bar{X}$，而正交性保内积：$\\sum_{i=1}^n Y_i^2 = \\sum_{i=1}^n X_i^2 \\implies \\sum_{i=2}^n Y_i^2 = \\sum X_i^2 - n\\bar{X}^2 = (n-1)S^2$。因 $(n-1)S^2$ 仅依赖 $Y_2,\\dots,Y_n$（均值为 $0$），故与 $Y_1$ 独立且除以 $\\sigma^2$ 服从 $\\chi^2(n-1)$！"}, {"oj": "教材精选题", "pid": "Sheng-2.3", "title": "利用 $t$ 分布与 $F$ 分布定义判别统计量分布", "diff": "中档", "hint": "破题思路：设 $X_1,\\dots,X_6$ i.i.d. $\\sim \\mathcal{N}(0, \\sigma^2)$，求使 $C \\frac{X_1+X_2+X_3}{\\sqrt{X_4^2+X_5^2+X_6^2}}$ 服从 $t$ 分布的常数 $C$ 及自由度。完整解答：分子 $U = \\frac{X_1+X_2+X_3}{\\sqrt{3}\\sigma} \\sim \\mathcal{N}(0,1)$；分母中 $V = \\frac{X_4^2+X_5^2+X_6^2}{\\sigma^2} \\sim \\chi^2(3)$ 且与 $U$ 独立。由 $t$ 分布定义 $\\frac{U}{\\sqrt{V/3}} \\sim t(3)$，代入化简得 $\\frac{X_1+X_2+X_3}{\\sqrt{X_4^2+X_5^2+X_6^2}} \\sim t(3)$，故 $C = 1$，自由度为 $3$。"}, {"oj": "教材精选题", "pid": "Sheng-2.4", "title": "$\\chi^2(n)$ 分布的期望、方差与分位数倒数关系", "diff": "基础", "hint": "破题思路：设 $Y \\sim \\chi^2(n)$，求 $E[Y]$ 与 $\\text{Var}(Y)$；并推导 $F_{1-\\alpha}(n_1, n_2) = \\frac{1}{F_\\alpha(n_2, n_1)}$。完整解答：(1) $Y = \\sum_{i=1}^n Z_i^2$（$Z_i \\sim \\mathcal{N}(0,1)$ 独立），$E[Z_i^2]=1$，$\\text{Var}(Z_i^2) = E[Z_i^4]-1 = 3-1 = 2$，故 $E[Y]=n, \\text{Var}(Y)=2n$；(2) 若 $F \\sim F(n_1,n_2)$，则 $1/F \\sim F(n_2,n_1)$。由 $P(F > F_\\alpha(n_1,n_2)) = \\alpha \\iff P(1/F < \\frac{1}{F_\\alpha(n_1,n_2)}) = \\alpha \\iff P(1/F > \\frac{1}{F_\\alpha(n_1,n_2)}) = 1-\\alpha$，即得倒数关系。"}]}, {"cid": "Sheng-Ch.07-P1", "title": "点估计：矩估计 (MoM)、极大似然 (MLE) 与 Cramér-Rao 下界", "summary": "第 7 章前半部分系统阐述参数点估计的构造与理论极限。方法上对比**矩估计（Method of Moments）**的样本矩替换思想与 **Fisher 极大似然估计（MLE）**的概率最大化准则，详细推导对数似然方程 $\\frac{\\partial \\ln L(\\theta)}{\\partial \\theta} = 0$ 及非正则边界情形（如均匀分布 $U(0, \\theta)$）的求解策略。理论评估部分引入估计量的三大准则——无偏性、有效性（最小方差）与相合性（依概率收敛于真值），并给出信息论视角下的 **Cramér-Rao 不等式**：任何无偏估计的方差均不小于 Fisher 信息量的倒数 $\\frac{1}{n I(\\theta)}$。", "template_cpp": "【极大似然估计 (MLE) 与 Cramér-Rao 下界模板】\n1. 写出似然函数 $L(\\theta) = \\prod_{i=1}^n f(x_i; \\theta)$，取对数 $\\ell(\\theta) = \\sum_{i=1}^n \\ln f(x_i; \\theta)$。\n2. 若支撑集与 $\\theta$ 无关，解似然方程 $\\ell'(\\theta) = 0$ 并验证二阶导 $\\ell''(\\hat{\\theta}) < 0$；若支撑集依赖 $\\theta$（如 $0 < x_i < \\theta$），则利用单调性直接取次序统计量极值（如 $\\hat{\\theta}_{MLE} = X_{(n)}$）。\n3. Cramér-Rao 下界：$\\text{Var}(\\hat{\\theta}) \\ge \\frac{1}{n I(\\theta)}$，其中 $I(\\theta) = E\\left[\\left(\\frac{\\partial \\ln f(X;\\theta)}{\\partial \\theta}\\right)^2\\right] = -E\\left[\\frac{\\partial^2 \\ln f(X;\\theta)}{\\partial \\theta^2}\\right]$。", "pitfalls": "对均匀分布 $U(a,b)$ 或移位指数分布等支撑集依赖参数的分布，盲目对似然函数求导令其为零（导数恒不为零，极值在边界 $\\min X_i$ 或 $\\max X_i$ 处取到）；误以为极大似然估计总是无偏的（反例：正态总体方差 MLE $\\hat{\\sigma}^2 = \\frac{1}{n}\\sum(X_i-\\bar{X})^2$ 有偏）；忽略 MLE 的“函数不变性”（即 $\\widehat{g(\\theta)}_{MLE} = g(\\hat{\\theta}_{MLE})$）。", "workbench_tags": ["极大似然估计", "矩估计", "无偏性", "Cramér-Rao下界"], "problems": [{"oj": "教材精选题", "pid": "Sheng-3.1", "title": "均匀分布 $U(0, \\theta)$ 的矩估计与极大似然估计对比", "diff": "基础", "hint": "破题思路：对比 $X_1,\\dots,X_n \\sim U(0, \\theta)$ 的两种估计并检验无偏性与相合性。完整解答：(1) 矩估计：$E[X] = \\theta/2 = \\bar{X} \\implies \\hat{\\theta}_1 = 2\\bar{X}$，无偏且方差 $\\frac{\\theta^2}{3n}$；(2) MLE：$L(\\theta) = \\theta^{-n} \\mathbb{I}(X_{(n)} \\le \\theta)$，在 $\\theta \\ge X_{(n)}$ 上严格递减，故 $\\hat{\\theta}_2 = X_{(n)}$；(3) $E[X_{(n)}] = \\frac{n}{n+1}\\theta$（有偏但渐近无偏），均方误差 $\\text{MSE} = \\frac{2\\theta^2}{(n+1)(n+2)} = O(1/n^2)$，精度远高于矩估计的 $O(1/n)$！"}, {"oj": "教材精选题", "pid": "Sheng-3.2", "title": "未知均值与方差下正态参数的 MLE 与有偏性", "diff": "中档", "hint": "破题思路：求 $\\mathcal{N}(\\mu, \\sigma^2)$ 两参数的联合极大似然估计。完整解答：对数似然 $\\ell(\\mu, \\sigma^2) = -\\frac{n}{2}\\ln(2\\pi) - \\frac{n}{2}\\ln(\\sigma^2) - \\frac{1}{2\\sigma^2}\\sum_{i=1}^n (x_i - \\mu)^2$。对 $\\mu$ 求偏导置零得 $\\hat{\\mu} = \\bar{X}$；代入后对 $\\sigma^2$ 求偏导置零得 $\\hat{\\sigma}^2 = \\frac{1}{n}\\sum_{i=1}^n (X_i - \\bar{X})^2$。因 $E[\\hat{\\sigma}^2] = \\frac{n-1}{n}\\sigma^2 \\neq \\sigma^2$，故 MLE 有偏。"}, {"oj": "教材精选题", "pid": "Sheng-3.3", "title": "Poisson 分布与指数分布的 Cramér-Rao 有效估计验证", "diff": "中档", "hint": "破题思路：证明 $\\bar{X}$ 达到 Poisson($\\lambda$) 参数 $\\lambda$ 的 Cramér-Rao 方差下界。完整解答：$\\ln f(x;\\lambda) = x\\ln\\lambda - \\lambda - \\ln(x!)$。一阶导 $\\frac{x}{\\lambda}-1$，二阶导 $-\\frac{x}{\\lambda^2}$。故 Fisher 信息 $I(\\lambda) = -E[-X/\\lambda^2] = \\frac{1}{\\lambda}$。CR 下界为 $\\frac{1}{n I(\\lambda)} = \\frac{\\lambda}{n}$。而 $\\text{Var}(\\bar{X}) = \\frac{\\lambda}{n}$ 恰好达到下界，故 $\\bar{X}$ 为一致最小方差无偏估计（UMVUE）。"}, {"oj": "教材精选题", "pid": "Sheng-3.4", "title": "截断/移位指数分布 $f(x;\\theta) = e^{-(x-\\theta)}$ ($x\\ge\\theta$) 的估计", "diff": "压轴", "hint": "破题思路：求位置参数 $\\theta$ 的矩估计与 MLE，并构造无偏修正。完整解答：(1) $E[X] = \\theta + 1 \\implies \\hat{\\theta}_{MoM} = \\bar{X} - 1$；(2) $L(\\theta) = \\exp(-\\sum(x_i-\\theta)) \\mathbb{I}(\\theta \\le X_{(1)})$，关于 $\\theta$ 严格递增，故 $\\hat{\\theta}_{MLE} = X_{(1)}$；(3) 因 $X_{(1)} - \\theta \\sim \\text{Exp}(n)$，故 $E[X_{(1)}] = \\theta + \\frac{1}{n}$，无偏修正为 $X_{(1)} - \\frac{1}{n}$。"}]}, {"cid": "Sheng-Ch.07-P2-08", "title": "区间估计与假设检验（Neyman-Pearson 框架）", "summary": "第 7 章后半部与第 8 章构建了频率学派统计推断的完整双翼：**置信区间（Confidence Interval）**与**假设检验（Hypothesis Testing）**。区间估计通过构造不含未知参数的枢轴量（Pivot，如正态均值的 $Z/t$ 枢轴量、方差的 $\\chi^2$ 枢轴量），反解出包含真参数的随机区间；假设检验则基于小概率反证法思想，系统区分两类错误（第 I 类弃真错误 $\\alpha$ 与第 II 类取伪错误 $\\beta$），讲解单双侧检验、$p$-值（观察到的最小显著性水平）的实质，并阐明置信区间与双侧假设检验之间的精确对偶关系及 Neyman-Pearson 最强检验引理。", "template_cpp": "【正态总体均值与方差置信区间及假设检验枢轴量汇总】\n1. 单正态均值 $\\mu$（$\\sigma^2$ 已知）：$Z = \\frac{\\bar{X}-\\mu}{\\sigma/\\sqrt{n}} \\sim \\mathcal{N}(0,1) \\implies \\bar{X} \\pm z_{\\alpha/2}\\frac{\\sigma}{\\sqrt{n}}$。\n2. 单正态均值 $\\mu$（$\\sigma^2$ 未知）：$T = \\frac{\\bar{X}-\\mu}{S/\\sqrt{n}} \\sim t(n-1) \\implies \\bar{X} \\pm t_{\\alpha/2}(n-1)\\frac{S}{\\sqrt{n}}$。\n3. 单正态方差 $\\sigma^2$（$\\mu$ 未知）：$\\chi^2 = \\frac{(n-1)S^2}{\\sigma^2} \\sim \\chi^2(n-1) \\implies \\left[\\frac{(n-1)S^2}{\\chi^2_{\\alpha/2}(n-1)},\\; \\frac{(n-1)S^2}{\\chi^2_{1-\\alpha/2}(n-1)}\\right]$。", "pitfalls": "把“$95\\%$ 置信区间”错误解释为“真参数 $\\theta$ 落在这个固定数值区间内的概率为 $0.95$”（正确：随机区间以 $0.95$ 概率覆盖固定真值 $\\theta$）；将 $p$-值误解为“原假设 $H_0$ 为真的概率”；混淆双侧检验的临界值 $z_{\\alpha/2}$ 与单侧检验临界值 $z_\\alpha$；在检验 $\\sigma^2$ 未知的两个正态总体均值差时未先做 $F$ 检验确认方差是否齐性。", "workbench_tags": ["置信区间", "假设检验", "两类错误", "p值"], "problems": [{"oj": "教材精选题", "pid": "Sheng-4.1", "title": "未知方差正态均值的 $t$ 置信区间与单侧检验", "diff": "基础", "hint": "破题思路：某零件长度服从正态分布，抽测 $n=9$ 件得 $\\bar{x}=10.2, s=0.3$，求 $\\mu$ 的 $95\\%$ 置信区间并检验 $H_0: \\mu \\le 10$ vs $H_1: \\mu > 10$（$\\alpha=0.05$）。完整解答：(1) 查 $t_{0.025}(8) = 2.306$，置信区间 $10.2 \\pm 2.306 \\times \\frac{0.3}{3} = [9.9694, 10.4306]$；(2) 右侧检验统计量 $t = \\frac{10.2 - 10}{0.3/3} = 2.0$，查单侧临界值 $t_{0.05}(8) = 1.860$，因 $2.0 > 1.860$，在 $\\alpha=0.05$ 水平下拒绝 $H_0$（注意双侧区间包含 $10$ 但单侧检验拒绝 $10$，体现单双侧自由度/分位点差异）。"}, {"oj": "教材精选题", "pid": "Sheng-4.2", "title": "假设检验两类错误 $\\alpha, \\beta$ 的权衡与样本量计算", "diff": "中档", "hint": "破题思路：已知 $X \\sim \\mathcal{N}(\\mu, 4)$，检验 $H_0: \\mu=0$ vs $H_1: \\mu=1$，要求 $\\alpha \\le 0.05$ 且当 $\\mu=1$ 时 $\\beta \\le 0.10$，求最小样本量 $n$。完整解答：拒绝域 $\\bar{X} > c$。由 $\\alpha$ 条件：$\\frac{c - 0}{2/\\sqrt{n}} = z_{0.05} = 1.645$；由 $\\beta$ 条件：$P_{\\mu=1}(\\bar{X} \\le c) = \\Phi\\left(\\frac{c-1}{2/\\sqrt{n}}\\right) \\le 0.10 \\implies \\frac{c-1}{2/\\sqrt{n}} \\le -z_{0.10} = -1.282$。两式相减消去 $c$ 得 $\\frac{\\sqrt{n}}{2} \\ge 1.645 + 1.282 = 2.927 \\implies n \\ge 34.27$，取 $n=35$。"}, {"oj": "教材精选题", "pid": "Sheng-4.3", "title": "正态方差非对称 $\\chi^2$ 置信区间推导", "diff": "中档", "hint": "破题思路：为何正态方差 $\\sigma^2$ 的等尾置信区间写为 $\\left[\\frac{(n-1)S^2}{\\chi^2_{\\alpha/2}}, \\frac{(n-1)S^2}{\\chi^2_{1-\\alpha/2}}\\right]$（分母左大右小）？完整解答：从不等式 $P\\left(\\chi^2_{1-\\alpha/2}(n-1) \\le \\frac{(n-1)S^2}{\\sigma^2} \\le \\chi^2_{\\alpha/2}(n-1)\\right) = 1-\\alpha$ 出发，取倒数时不等号反向！故 $\\sigma^2$ 的下界对应较大的右分位点 $\\chi^2_{\\alpha/2}$，上界对应较小的左分位点 $\\chi^2_{1-\\alpha/2}$。"}, {"oj": "教材精选题", "pid": "Sheng-4.4", "title": "Pearson $\\chi^2$ 拟合优度检验与自由度损失", "diff": "压轴", "hint": "破题思路：用 $k$ 个组距检验样本是否服从含 $r$ 个未知参数的理论分布（如 Poisson($\\lambda$)）。完整解答：计算拟合统计量 $\\chi^2 = \\sum_{i=1}^k \\frac{(O_i - n\\hat{p}_i)^2}{n\\hat{p}_i}$，其中 $\\hat{p}_i$ 由 MLE 估计参数后算得。当 $n$ 充分大（通常要求每组期望频数 $n\\hat{p}_i \\ge 5$）时，该统计量渐近服从 $\\chi^2(k - 1 - r)$ 分布（总和约束减 $1$，每独立估计一个未知参数再减 $1$）。"}]}, {"cid": "Sheng-Ch.09-12", "title": "方差分析 (ANOVA)、线性回归与 Markov 链应用", "summary": "第 9–12 章将统计工具拓展至多因素方差分析、最小二乘线性回归以及随机过程初步。单因素方差分析通过平方和正交分解 $SS_T = SS_A + SS_E$（总离差平方和 = 组间效应 + 组内误差）构造 $F$ 统计量检验多组均值是否全相等，本质上避免了两两 $t$ 检验带来的第 I 类错误膨胀。一元线性回归利用正态误差假设给出斜率 $\\hat{\\beta}_1$ 的精确分布、$t$ 检验与预测区间，并引入决定系数 $R^2 = SS_R / SS_T$。最后补充平稳随机过程与 Markov 链状态分类，实现古典数理统计向现代随机建模的自然过渡。", "template_cpp": "【单因素 ANOVA 平方和分解与一元回归公式】\n1. 方差分析分解：$SS_T = SS_A + SS_E$，自由度 $(N-1) = (k-1) + (N-k)$。\n   检验统计量：$F = \\frac{SS_A / (k-1)}{SS_E / (N-k)} \\sim F(k-1, N-k)$（$H_0$ 成立时）。\n2. 一元回归 $y = \\beta_0 + \\beta_1 x + \\varepsilon$（$\\varepsilon \\sim \\mathcal{N}(0, \\sigma^2)$）：\n   $$\\hat{\\beta}_1 = \\frac{L_{xy}}{L_{xx}}, \\quad \\hat{\\beta}_0 = \\bar{y} - \\hat{\\beta}_1 \\bar{x}, \\quad \\hat{\\sigma}^2 = \\frac{SS_E}{n-2}, \\quad R^2 = \\frac{SS_R}{SS_T} = r^2$$", "pitfalls": "面对 $k \\ge 3$ 组均值比较时连续做 $\\binom{k}{2}$ 次两两 $t$ 检验导致整体假阳性率飙升（应先做 ANOVA 的 $F$ 检验）；在一元回归中残差自由度误写为 $n-1$（因估计了 $\\beta_0, \\beta_1$ 两个参数，应为 $n-2$）；混淆“置信区间”（针对均值响应 $E[Y|x_0]$）与“预测区间”（针对单个新观测 $Y_0$，多一项 $1$ 的方差）。", "workbench_tags": ["方差分析", "线性回归", "平方和分解", "决定系数"], "problems": [{"oj": "教材精选题", "pid": "Sheng-5.1", "title": "单因素 ANOVA 平方和恒等式 $SS_T = SS_A + SS_E$ 证明", "diff": "中档", "hint": "破题思路：证明 $\\sum_{i=1}^k \\sum_{j=1}^{n_i} (X_{ij} - \\bar{X})^2 = \\sum_{i=1}^k n_i (\\bar{X}_i - \\bar{X})^2 + \\sum_{i=1}^k \\sum_{j=1}^{n_i} (X_{ij} - \\bar{X}_i)^2$。完整解答：将左端内部拆项为 $(X_{ij} - \\bar{X}_i) + (\\bar{X}_i - \\bar{X})$ 并平方展开。交叉项为 $2\\sum_{i=1}^k (\\bar{X}_i - \\bar{X}) \\sum_{j=1}^{n_i} (X_{ij} - \\bar{X}_i)$。由于每组内离均差之和 $\\sum_{j=1}^{n_i} (X_{ij} - \\bar{X}_i) = 0$，交叉项恒为零，正交分解得证！"}, {"oj": "教材精选题", "pid": "Sheng-5.2", "title": "一元线性回归斜率 $\\hat{\\beta}_1$ 的方差与显著性 $t$ 检验", "diff": "基础", "hint": "破题思路：求 $\\text{Var}(\\hat{\\beta}_1)$ 并写出检验 $H_0: \\beta_1 = 0$ 的 $t$ 统计量。完整解答：将 $\\hat{\\beta}_1 = \\sum_{i=1}^n \\frac{x_i - \\bar{x}}{L_{xx}} Y_i$ 写成 $Y_i$ 的线性组合。由 $Y_i$ 独立且方差为 $\\sigma^2$，得 $\\text{Var}(\\hat{\\beta}_1) = \\sum \\frac{(x_i-\\bar{x})^2}{L_{xx}^2} \\sigma^2 = \\frac{\\sigma^2}{L_{xx}}$。用无偏估计 $\\hat{\\sigma}^2 = \\frac{SS_E}{n-2}$ 替换 $\\sigma^2$，得 $T = \\frac{\\hat{\\beta}_1 \\sqrt{L_{xx}}}{\\hat{\\sigma}} \\sim t(n-2)$（且 $T^2 = F$ 回归检验统计量）。"}, {"oj": "教材精选题", "pid": "Sheng-5.3", "title": "回归模型均值置信区间 vs 单点预测区间推导", "diff": "中档", "hint": "破题思路：在 $x = x_0$ 处，比较 $\\hat{Y}_0 = \\hat{\\beta}_0 + \\hat{\\beta}_1 x_0$ 估计 $E[Y|x_0]$ 与预测新观测 $Y_0 = \\beta_0 + \\beta_1 x_0 + \\varepsilon_0$ 的方差差异。完整解答：利用 $\\hat{\\beta}_0 = \\bar{Y} - \\hat{\\beta}_1 \\bar{x}$ 且 $\\bar{Y}$ 与 $\\hat{\\beta}_1$ 不相关，得 $\\text{Var}(\\hat{Y}_0) = \\text{Var}(\\bar{Y} + \\hat{\\beta}_1(x_0-\\bar{x})) = \\sigma^2 \\left(\\frac{1}{n} + \\frac{(x_0-\\bar{x})^2}{L_{xx}}\\right)$。而预测误差 $Y_0 - \\hat{Y}_0$ 还包含新噪声 $\\varepsilon_0$（与历史样本独立），故方差多出 $\\sigma^2$，变为 $\\sigma^2 \\left(1 + \\frac{1}{n} + \\frac{(x_0-\\bar{x})^2}{L_{xx}}\\right)$。"}, {"oj": "教材精选题", "pid": "Sheng-5.4", "title": "Gauss-Markov 定理（OLS 是最佳线性无偏估计 BLUE）", "diff": "压轴", "hint": "破题思路：在仅假设 $E[\\varepsilon_i]=0, \\text{Var}(\\varepsilon_i)=\\sigma^2$ 且不相关（无需正态）条件下，证最小二乘估计 $\\hat{\\beta}_1$ 在所有线性无偏估计中方差最小。完整解答：设任意线性估计 $\\tilde{\\beta}_1 = \\sum c_i Y_i$。无偏性要求 $E[\\tilde{\\beta}_1] = \\beta_0 \\sum c_i + \\beta_1 \\sum c_i x_i \\equiv \\beta_1 \\implies \\sum c_i = 0, \\sum c_i x_i = 1$。记 $c_i = w_i + d_i$，其中 $w_i = \\frac{x_i-\\bar{x}}{L_{xx}}$ 为 OLS 权重。由约束条件易证 $\\sum w_i d_i = 0$，从而 $\\text{Var}(\\tilde{\\beta}_1) = \\sigma^2 \\sum (w_i + d_i)^2 = \\sigma^2 (\\sum w_i^2 + \\sum d_i^2) \\ge \\text{Var}(\\hat{\\beta}_1)$。"}]}]}, {"id": "gh_bupt_prob", "name": "🎓 北邮 CS 学长攻略（概率统计）", "author": "faranten/bupt-cs-gallery & Yokumii · GitHub", "level": "校内考情", "repo_url": "https://github.com/faranten/bupt-cs-gallery", "chapters": [{"cid": "BUPT-PROB-01", "title": "北邮概率论与数理统计考核与复习指南", "summary": "北邮《概率论与数理统计》（4学分，部分培养方案含期中小论文）整体节奏中规中矩，从知识点编排到期末考题均具有较强的套路性，往年真题参考价值极高。重点吃透条件概率/全概率贝叶斯、二维连续型变量边缘与独立性、数字特征期望方差、大数定律与中心极限定理、极大似然估计与置信区间。", "template_cpp": "拿分关键：二维密度积分域画图 + 常见分布期望方差记忆表 + 往年真题近5年全刷。", "pitfalls": "二维随机变量函数分布求积分上下限极易出错，务必先画出积分区域再定限。", "workbench_tags": ["北邮考情", "概率统计"], "problems": []}]}];
window.__WB_CHEATSHEET__ = {"title": "概率论与数理统计考前1页纸速查卡", "sections": [{"heading": "一、古典概型与三大核心公式", "items": [{"name": "容斥原理（加法公式）", "formula": "$P(A\\cup B)=P(A)+P(B)-P(AB)$", "note": "若 $A,B$ 互斥，则 $P(AB)=0$；若 $A,B$ 独立，则 $P(AB)=P(A)P(B)$。"}, {"name": "条件概率与乘法公式", "formula": "$P(B|A)=\\frac{P(AB)}{P(A)}$（$P(A)>0$）；$P(ABC)=P(A)P(B|A)P(C|AB)$", "note": "条件概率也满足概率公理化三条性质，如 $P(\\bar{B}|A)=1-P(B|A)$。"}, {"name": "全概率公式", "formula": "$P(B) = \\sum_{i=1}^n P(A_i)P(B|A_i)$", "note": "要求 $\\{A_i\\}$ 为样本空间的一个完备事件组（两两互斥且并集为全集）。"}, {"name": "贝叶斯（Bayes）公式", "formula": "$P(A_k|B) = \\frac{P(A_k)P(B|A_k)}{\\sum_{i=1}^n P(A_i)P(B|A_i)}$", "note": "“由果溯因”：先验概率 $P(A_k)$ 乘以似然 $P(B|A_k)$ 再归一化。"}]}, {"heading": "二、常见概率分布速查表", "items": [{"name": "二项分布 $X \\sim B(n, p)$", "formula": "$P(X=k)=\\binom{n}{k}p^k(1-p)^{n-k}$；$E(X)=np$，$D(X)=np(1-p)$", "note": "可加性：独立同参数 $p$ 的二项分布之和仍服从 $B(n_1+n_2, p)$。"}, {"name": "泊松分布 $X \\sim P(\\lambda)$", "formula": "$P(X=k)=\\frac{\\lambda^k}{k!}e^{-\\lambda}$；$E(X)=\\lambda$，$D(X)=\\lambda$", "note": "$n$ 大 $p$ 小（$np=\\lambda$）时二项分布可用泊松分布近似；独立泊松之和为 $P(\\lambda_1+\\lambda_2)$。"}, {"name": "均匀分布 $X \\sim U(a, b)$", "formula": "$f(x)=\\frac{1}{b-a}$；$E(X)=\\frac{a+b}{2}$，$D(X)=\\frac{(b-a)^2}{12}$", "note": "落在子区间 $[c,d]\\subset[a,b]$ 的概率只与区间长度 $\\frac{d-c}{b-a}$ 有关。"}, {"name": "指数分布 $X \\sim E(\\lambda)$", "formula": "$f(x)=\\lambda e^{-\\lambda x}\\ (x>0)$；$E(X)=\\frac{1}{\\lambda}$，$D(X)=\\frac{1}{\\lambda^2}$", "note": "唯一具有无记忆性的连续分布：$P(X > s+t \\mid X > s) = P(X > t)$。"}, {"name": "正态分布 $X \\sim N(\\mu, \\sigma^2)$", "formula": "$Z = \\frac{X-\\mu}{\\sigma} \\sim N(0,1)$；$E(X)=\\mu$，$D(X)=\\sigma^2$", "note": "记住 $3\\sigma$ 原则：$1\\sigma$ 约 $68.3\\%$，$2\\sigma$ 约 $95.4\\%$，$3\\sigma$ 约 $99.7\\%$。"}]}, {"heading": "三、二维随机变量与独立性", "items": [{"name": "边缘密度与边缘分布", "formula": "$f_X(x) = \\int_{-\\infty}^{+\\infty} f(x,y)dy$；$f_Y(y) = \\int_{-\\infty}^{+\\infty} f(x,y)dx$", "note": "求积分时务必画出联合非零区域，确定上下限（常与 $x$ 或 $y$ 有关）。"}, {"name": "条件概率密度", "formula": "$f_{Y|X}(y|x) = \\frac{f(x,y)}{f_X(x)}$（$f_X(x)>0$）", "note": "条件期望 $E(Y|X=x) = \\int y f_{Y|X}(y|x)dy$；全期望公式 $E(Y)=E[E(Y|X)]$。"}, {"name": "独立性充要条件", "formula": "$f(x,y) = f_X(x)f_Y(y)$（a.e.）或 $F(x,y) = F_X(x)F_Y(y)$", "note": "非矩形支撑区域（如三角形 $0<x<y<1$）上的联合密度一定不独立！"}, {"name": "卷积公式（$Z = X + Y$）", "formula": "$f_Z(z) = \\int_{-\\infty}^{+\\infty} f(x, z-x)dx$；独立时为 $\\int f_X(x)f_Y(z-x)dx$", "note": "独立正态线性组合：$\\sum a_i X_i \\sim N(\\sum a_i \\mu_i, \\sum a_i^2 \\sigma_i^2)$。"}]}, {"heading": "四、数字特征、协方差与相关系数", "items": [{"name": "方差与协方差计算公式", "formula": "$D(X)=E(X^2)-[E(X)]^2$；$\\text{Cov}(X,Y)=E(XY)-E(X)E(Y)$", "note": "$D(aX\\pm bY) = a^2D(X)+b^2D(Y)\\pm 2ab\\text{Cov}(X,Y)$。"}, {"name": "相关系数 $\\rho_{XY}$", "formula": "$\\rho_{XY} = \\frac{\\text{Cov}(X,Y)}{\\sqrt{D(X)D(Y)}}$，且 $|\\rho_{XY}| \\le 1$", "note": "$|\\rho_{XY}|=1 \\iff X,Y$ 几乎必然存在线性关系 $Y=aX+b$。"}, {"name": "独立性与不相关关系", "formula": "独立 $\\implies$ 不相关（$\\rho=0$），但一般不相关 $\\not\\Rightarrow$ 独立", "note": "特例：二维正态分布 $(X,Y)$ 中，独立 $\\iff$ 不相关（$\\rho=0$）。"}, {"name": "切比雪夫（Chebyshev）不等式", "formula": "$P(|X-E(X)| \\ge \\varepsilon) \\le \\frac{D(X)}{\\varepsilon^2}$", "note": "无需知道具体分布，仅用均值和方差即可给出尾概率上界。"}]}, {"heading": "五、极限定理与三大抽样分布", "items": [{"name": "大数定律（LLN）与中心极限定理（CLT）", "formula": "$\\bar{X}_n \\xrightarrow{P} \\mu$；$\\frac{\\sum X_i - n\\mu}{\\sqrt{n}\\sigma} \\xrightarrow{d} N(0,1)$", "note": "CLT 要求独立同分布且方差有限（林德伯格-列维），用于正态近似二项/求和分布。"}, {"name": "$\\chi^2$ 分布", "formula": "$Z_1^2 + \\dots + Z_n^2 \\sim \\chi^2(n)$；$E(\\chi^2)=n$，$D(\\chi^2)=2n$", "note": "正态样本方差结论：$\\frac{(n-1)S^2}{\\sigma^2} \\sim \\chi^2(n-1)$，且 $\\bar{X}$ 与 $S^2$ 独立。"}, {"name": "$t$ 分布", "formula": "$T = \\frac{Z}{\\sqrt{Y/n}} \\sim t(n)$（$Z\\sim N(0,1), Y\\sim\\chi^2(n)$ 独立）", "note": "未知 $\\sigma^2$ 时用 $T = \\frac{\\bar{X}-\\mu}{S/\\sqrt{n}} \\sim t(n-1)$ 构造均值区间与检验。"}, {"name": "$F$ 分布", "formula": "$F = \\frac{X/n_1}{Y/n_2} \\sim F(n_1, n_2)$，满足 $F_{1-\\alpha}(n_1,n_2) = \\frac{1}{F_\\alpha(n_2,n_1)}$", "note": "若 $T\\sim t(n)$ 则 $T^2 \\sim F(1, n)$；用于两正态总体方差比检验。"}]}, {"heading": "六、参数估计与假设检验", "items": [{"name": "矩估计与最大似然估计（MLE）", "formula": "矩估计令 $\\alpha_k = A_k$；MLE 最大化 $L(\\theta)=\\prod f(x_i;\\theta)$", "note": "若求导无驻点（如 $U(0,\\theta)$），MLE 在边界取极值 $\\hat{\\theta} = \\max(X_i)$。"}, {"name": "无偏性与有效性", "formula": "无偏：$E(\\hat{\\theta})=\\theta$；均方误差 $\\text{MSE}=D(\\hat{\\theta}) + [E(\\hat{\\theta})-\\theta]^2$", "note": "样本方差 $S^2 = \\frac{1}{n-1}\\sum (X_i-\\bar{X})^2$ 才是 $\\sigma^2$ 的无偏估计（除以 $n-1$）。"}, {"name": "两类错误与显著性水平 $\\alpha$", "formula": "第一类错误（弃真）：$P(\\text{拒绝 }H_0 \\mid H_0\\text{ 真}) = \\alpha$；第二类（取伪）：$\\beta$", "note": "样本量 $n$ 固定时，$\\alpha$ 与 $\\beta$ 此消彼长；同时减小只能增大 $n$。"}, {"name": "置信区间（正态均值已知/未知方差）", "formula": "$\\bar{X} \\pm z_{\\alpha/2}\\frac{\\sigma}{\\sqrt{n}}$ 或 $\\bar{X} \\pm t_{\\alpha/2}(n-1)\\frac{S}{\\sqrt{n}}$", "note": "置信水平 $1-\\alpha$ 指重复抽样中随机区间覆盖真参数 $\\mu$ 的概率。"}]}, {"heading": "七、概率统计高频易错陷阱", "items": [{"name": "互斥 vs 独立混淆", "formula": "对于 $P(A)>0, P(B)>0$ 的事件，互斥与独立必不能同时成立", "note": "互斥是 $AB=\\emptyset \\Rightarrow P(AB)=0$；独立是 $P(AB)=P(A)P(B)>0$。"}, {"name": "密度函数 $f(x)$ 可大于 $1$", "formula": "仅需 $f(x)\\ge 0$ 且 $\\int_{-\\infty}^{+\\infty} f(x)dx = 1$", "note": "分布函数 $F(x) \\in [0,1]$ 且右连续，但密度函数在窄区间上完全可以大于 $1$。"}, {"name": "连续型随机变量单点概率为 $0$", "formula": "$P(X=a)=0$，但 $P(X=a)=0$ 不代表 $\\{X=a\\}$ 是不可能事件", "note": "同理 $P(A)=1$ 不代表 $A$ 是必然事件（仅代表几乎必然）。"}, {"name": "期望与方差的非线性陷阱", "formula": "$E(g(X)) \\ne g(E(X))$；$D(X-Y) = D(X)+D(Y)$（独立时是加不是减！）", "note": "独立随机变量之差的方差等于方差之和：$D(aX-bY)=a^2D(X)+b^2D(Y)$。"}]}]};
